<?php
namespace App\Http\Controllers;

use App\Models\{ApprovalHistory,EditRequest,WorkBreak};
use App\Services\RequestNotifier;
use Illuminate\Http\Request;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;

class EditRequestController extends Controller
{
    public function mine(Request $request){$requests=$request->user()->editRequests()->latest()->get();return view('edit_requests.mine',compact('requests'));}
    public function index(Request $request){$this->authorize('viewAny',EditRequest::class);$user=$request->user();$query=EditRequest::with(['user','timeClock','histories.actor']);if(!$user->hasPermission('requests.finalize'))$query->whereHas('user',fn($q)=>$q->where('manager_id',$user->id)->orWhereIn('department_id',$user->hodDepartments()->pluck('departments.id')));$requests=$query->latest()->paginate(20);return view('edit_requests.index',compact('requests'));}
    public function store(Request $request,RequestNotifier $notifier){$data=$request->validate(['requested_clock_in'=>'required|date','requested_break_in'=>'nullable|date','requested_break_out'=>'nullable|date|after_or_equal:requested_break_in','reason'=>'required|string|max:2000','request_type'=>['required',Rule::in(EditRequest::TYPES)],'break_reason'=>'nullable|string|max:255']);$requested=Carbon::parse($data['requested_clock_in']);if(!$requested->between(now()->startOfWeek(),now()->endOfWeek()))return back()->with('error','Requested time must be within the current week.');if($request->user()->editRequests()->whereBetween('created_at',[now()->startOfMonth(),now()->endOfMonth()])->count()>=EditRequest::MONTHLY_LIMIT)return back()->with('error','Monthly limit of 3 edit requests reached.');$clock=$request->user()->timeClocks()->whereDate('clock_in',$requested)->first()??$request->user()->timeClocks()->latest()->first();if(!$clock)return back()->with('error','No matching time record found.');$item=$request->user()->editRequests()->create($data+['time_clock_id'=>$clock->id,'department'=>$request->user()->department,'status'=>'pending_manager']);$notifier->created($item->load('user'),'attendance correction');return back()->with('success','Edit request submitted for manager approval.');}
    public function decision(Request $request,EditRequest $editRequest,string $decision,RequestNotifier $notifier){$this->authorize('decide',$editRequest);abort_unless(in_array($decision,['approve','reject'],true),404);abort_unless(in_array($editRequest->status,['pending','pending_manager','pending_admin'],true),422,'This request has already been resolved.');$data=$request->validate(['note'=>'nullable|string|max:1000']);$previous=$editRequest->status;$admin=$request->user()->hasPermission('requests.finalize');DB::transaction(function()use($request,$editRequest,$decision,$data,$previous,$admin){if($admin){$status=$decision==='approve'?'approved':'rejected';$editRequest->update(['approved_by_admin'=>$decision==='approve','admin_approved_by'=>$request->user()->id,'status'=>$status,'resolved_at'=>now(),'manager_note'=>$data['note']??null]);if($decision==='approve')$this->apply($editRequest);$stage='admin';}else{abort_unless($editRequest->managerActionable(),422,'Requests older than one week cannot be changed.');$status=$decision==='approve'?'pending_admin':'rejected';$editRequest->update(['approved_by_manager'=>$decision==='approve','manager_approved_by'=>$request->user()->id,'status'=>$status,'resolved_at'=>$decision==='reject'?now():null,'manager_note'=>$data['note']??null]);$stage='manager';}ApprovalHistory::create(['approvable_type'=>EditRequest::class,'approvable_id'=>$editRequest->id,'acted_by'=>$request->user()->id,'stage'=>$stage,'action'=>$decision,'previous_status'=>$previous,'new_status'=>$status,'note'=>$data['note']??null]);});$notifier->decided($editRequest->load('user'),'attendance correction',$editRequest->status);return back()->with('success','Request '.str_replace('_',' ',$editRequest->status).'.');}
    private function apply(EditRequest $item):void{$clock=$item->timeClock()->with(['breaks','user'])->firstOrFail();if(in_array($item->request_type,['clock_in','clock_tower_not_working'],true))$clock->update(['clock_in'=>$item->requested_clock_in]);elseif($item->request_type==='forgot_break_start')WorkBreak::firstOrCreate(['time_clock_id'=>$item->time_clock_id,'break_in'=>$item->requested_break_in??$item->requested_clock_in],['break_out'=>$item->requested_break_out,'break_type'=>$item->break_reason?:'Corrected Break']);elseif($item->request_type==='forgot_break_end'){$break=$clock->breaks()->whereNull('break_out')->latest('break_in')->first();$break?->update(['break_out'=>$item->requested_break_out??$item->requested_clock_in]);}$clock->refresh()->recalculateAfterCorrection();}
}
